\set ON_ERROR_STOP on
BEGIN READ ONLY;
SELECT jsonb_build_object(
'identity',(SELECT to_jsonb(x) FROM (SELECT current_database() database,current_user username,version(),current_setting('search_path') search_path,current_setting('transaction_read_only') read_only,pg_postmaster_start_time() started) x),
'roles',(SELECT jsonb_agg(to_jsonb(x)) FROM (SELECT rolname,rolsuper,rolinherit,rolcreaterole,rolcreatedb,rolcanlogin,rolreplication,rolbypassrls FROM pg_roles WHERE rolname=current_user OR rolname LIKE 'capstone%') x),
'schemas',(SELECT jsonb_agg(to_jsonb(x)) FROM (SELECT oid,nspname,pg_get_userbyid(nspowner) owner FROM pg_namespace) x),
'extensions',(SELECT jsonb_agg(to_jsonb(x)) FROM (SELECT e.extname,e.extversion,n.nspname FROM pg_extension e JOIN pg_namespace n ON n.oid=e.extnamespace) x),
'relations',(SELECT jsonb_agg(to_jsonb(x)) FROM (SELECT c.oid,n.nspname,c.relname,c.relkind,pg_get_userbyid(c.relowner) owner,c.relrowsecurity,c.relforcerowsecurity,c.relacl FROM pg_class c JOIN pg_namespace n ON n.oid=c.relnamespace WHERE n.nspname !~ '^pg_' AND n.nspname<>'information_schema' ORDER BY 2,3) x),
'columns',(SELECT jsonb_agg(to_jsonb(x)) FROM (SELECT c.relname,a.attname,a.attnum,format_type(a.atttypid,a.atttypmod) type,a.attnotnull,a.attidentity,a.attgenerated,pg_get_expr(d.adbin,d.adrelid) default_expression FROM pg_attribute a JOIN pg_class c ON c.oid=a.attrelid JOIN pg_namespace n ON n.oid=c.relnamespace LEFT JOIN pg_attrdef d ON d.adrelid=a.attrelid AND d.adnum=a.attnum WHERE n.nspname='public' AND a.attnum>0 AND NOT a.attisdropped AND c.relkind IN ('r','p','v','m','f') ORDER BY c.relname,a.attnum) x),
'constraints',(SELECT jsonb_agg(to_jsonb(x)) FROM (SELECT co.oid,co.conname,co.contype,co.conrelid::regclass::text relation,co.confrelid::regclass::text referenced_relation,co.convalidated,co.condeferrable,co.condeferred,pg_get_constraintdef(co.oid,true) definition FROM pg_constraint co JOIN pg_namespace n ON n.oid=co.connamespace WHERE n.nspname='public' ORDER BY relation,co.conname) x),
'indexes',(SELECT jsonb_agg(to_jsonb(x)) FROM (SELECT c.relname relation,i.indexrelid::regclass::text index_name,am.amname,i.indisunique,i.indisprimary,i.indisvalid,pg_get_indexdef(i.indexrelid) definition FROM pg_index i JOIN pg_class c ON c.oid=i.indrelid JOIN pg_namespace n ON n.oid=c.relnamespace JOIN pg_class ic ON ic.oid=i.indexrelid JOIN pg_am am ON am.oid=ic.relam WHERE n.nspname='public') x),
'routines',(SELECT jsonb_agg(to_jsonb(x)) FROM (SELECT p.oid,n.nspname,p.proname,p.prokind,pg_get_function_identity_arguments(p.oid) arguments,l.lanname,p.prosecdef,p.proconfig,pg_get_functiondef(p.oid) definition,(SELECT e.extname FROM pg_depend d JOIN pg_extension e ON e.oid=d.refobjid WHERE d.classid='pg_proc'::regclass AND d.objid=p.oid AND d.deptype='e') extension FROM pg_proc p JOIN pg_namespace n ON n.oid=p.pronamespace JOIN pg_language l ON l.oid=p.prolang WHERE n.nspname !~ '^pg_' AND n.nspname<>'information_schema' AND p.prokind IN ('f','p') ORDER BY p.proname) x),
 'triggers',(SELECT jsonb_agg(to_jsonb(x)) FROM (SELECT t.oid,t.tgname,t.tgrelid::regclass::text relation,t.tgfoid::regprocedure::text function,t.tgenabled,t.tgisinternal,t.tgconstraint,pg_get_triggerdef(t.oid,true) definition FROM pg_trigger t JOIN pg_class c ON c.oid=t.tgrelid JOIN pg_namespace n ON n.oid=c.relnamespace WHERE n.nspname='public' ORDER BY relation,t.tgname) x),
'views',(SELECT jsonb_agg(to_jsonb(x)) FROM (SELECT c.oid,c.relname,c.relkind,pg_get_viewdef(c.oid,true) definition FROM pg_class c JOIN pg_namespace n ON n.oid=c.relnamespace WHERE n.nspname='public' AND c.relkind IN ('v','m')) x),
'sequences',(SELECT jsonb_agg(to_jsonb(x)) FROM (SELECT schemaname,sequencename,sequenceowner,data_type,start_value,min_value,max_value,increment_by,cycle,cache_size FROM pg_sequences WHERE schemaname='public') x),
'dependencies',(SELECT jsonb_agg(to_jsonb(x)) FROM (SELECT d.classid::regclass::text class,d.objid,d.objsubid,d.refclassid::regclass::text refclass,d.refobjid,d.refobjsubid,d.deptype,pg_describe_object(d.classid,d.objid,d.objsubid) object,pg_describe_object(d.refclassid,d.refobjid,d.refobjsubid) referenced_object FROM pg_depend d WHERE (d.classid='pg_class'::regclass AND d.objid IN (SELECT c.oid FROM pg_class c JOIN pg_namespace n ON n.oid=c.relnamespace WHERE n.nspname='public')) OR (d.classid='pg_proc'::regclass AND d.objid IN (SELECT oid FROM pg_proc WHERE pronamespace='public'::regnamespace)) OR (d.classid='pg_trigger'::regclass AND d.objid IN (SELECT oid FROM pg_trigger WHERE tgrelid IN (SELECT oid FROM pg_class WHERE relnamespace='public'::regnamespace))) OR (d.classid='pg_constraint'::regclass AND d.objid IN (SELECT oid FROM pg_constraint WHERE connamespace='public'::regnamespace)) OR (d.classid='pg_rewrite'::regclass AND d.objid IN (SELECT oid FROM pg_rewrite WHERE ev_class IN (SELECT oid FROM pg_class WHERE relnamespace='public'::regnamespace)))) x),
'policies',(SELECT jsonb_agg(to_jsonb(x)) FROM (SELECT * FROM pg_policies WHERE schemaname='public') x),
'alembic_history',(SELECT jsonb_agg(version_num) FROM public.alembic_version)
);
COMMIT;
